package com.c203.limit.domain.admin.entity;import java.time.OffsetDateTime;import jakarta.persistence.*;@Entity@Table(name="member_role",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","role_code"}))public class MemberRoleAssignment{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="member_role_id")private Long id;@Column(name="user_id",nullable=false)private Long memberId;@Column(name="role_code",nullable=false)private String roleCode;@Column(name="granted_admin_id",nullable=false)private Long grantedAdminId;@Column(name="granted_at",nullable=false)private OffsetDateTime grantedAt;protected MemberRoleAssignment(){}public static MemberRoleAssignment grant(Long member,String role,Long admin){var a=new MemberRoleAssignment();a.memberId=member;a.roleCode=role;a.grantedAdminId=admin;a.grantedAt=OffsetDateTime.now();return a;}public Long getId(){return id;}public Long getMemberId(){return memberId;}public String getRoleCode(){return roleCode;}public OffsetDateTime getGrantedAt(){return grantedAt;}}
